    write(BASE/'dependency-license-review.json',dict(status='source_rights_unresolved',root='Pinned licenseAPI404 and no root license in complete retained tree',runtime='Imports DataRobot,pandas,matplotlib,seaborn without a complete lock in selected notebook',data='Modified clinical subset provenance/rights not authenticated',server='Selected client/server/model/API entitlement,support and price not established',copy_or_port_allowed=False,agreement_accepted=False,integration_allowed=False,evidence=[ref(BASE/'primary-review.json','Original source and rights omission')]))
    write(BASE/'conversion-contract.json',dict(status='proposed_reference_only',inputs=['request_id','question_version','population_treatment_outcome_clocks','eligible_covariates','data_schema_row_digests','class_mapping','project_model_prediction_job','propensity_fit_and_target_weight_rule','uncertainty_law','rights_profile','deadline_budget'],outputs=['typed_execution_status','scientific_status','complete_row_alignment','finite_propensities','overlap_weight_diagnostics','target_effect_or_refusal','uncertainty_assumptions','all_attempt_costs'],refusals=['Unestablished source/data rights','Missing/duplicate prediction rows','Wrong positive class','Boundary or nonfinite propensity','Unsupported assignment truth','Post-treatment covariate selection','Stale model/query digest','Unjustified uncertainty'],integration_allowed=False,native_execution=False))
    fixtures=[('known_propensity','Exact finite assignment/effect oracle'),('class_swap','Class meaning mismatch refused'),('missing_duplicate_rows','No silent row loss or duplicate weight'),('boundary_probability','Typed invalid/unsupported positivity result'),('near_positivity','Predeclared diagnostics and target rule;no hidden clipping'),('post_treatment_feature','Covariate rejected or query redesigned'),('failed_prediction','Failure preserved in denominator'),('stale_model_query','Digest mismatch refused'),('sampling_dependence','Uncertainty matches declared independent/cluster/panel law')]
    write(BASE/'qualification-plan.json',dict(status='proposed_not_executed',arms=['Fixed conventional propensity method','Permitted frozen DataRobot profile','Contract-wrapped workflow with matched causal estimator'],fixtures=[dict(name=n,oracle=o,status='not_run') for n,o in fixtures],freezes=['Generated law,target,feature timing and model selection','Task/version/held-out split','Weight/overlap rules and nuisance-fitting strategy','Uncertainty law,tolerances and scoring','Supported entitled artifacts and all costs'],data_scope='Generated causal truth;permitted public workflow stress without invented assignment truth',denominator='All requests,attempts,completions,refusals,failures and admissible outputs',native_execution=False))
