    ev=[ref(BASE/n,'Reviewed decision') for n in ['review.json','choice.json','conversion-contract.json','dependency-license-review.json','qualification-plan.json']]
    findings=['Pinned notebook,official overview,rights and maintenance limits bound','Targets,uncertainty,alternatives,costs,owners and revisit trigger explicit','Reference only;contracts/oracles proposed;integration disallowed']
    result=run.ledger.receipt_template(node);result.update(outcome='pass',execution='performed',scope=value['scope'],reviewer=dict(name='Codex author/coordinator',kind='author'),outputs=[ref(output,'Named reference disposition')],criteria=[dict(index=i,verdict='pass',finding=f,evidence=ev) for i,f in enumerate(findings)],limitations=LIMITS,capabilities=[],nonexecution_reason='',revisit_trigger=value['revisit_trigger'])
    run.validate_receipt(ROOT,merged,node,result,len(state['execution_program']['turns']));verify_bindings(result);write(BASE/'operation-receipt.json',result);print('DataRobot receipt prepared.')
